hsd:
Driver = GeometryOptimisation {
  Optimiser = LBFGS {}
  LatticeOpt = No
  MaxSteps = 3000
  Convergence { GradElem = 1e-07 }
}
Geometry = GenFormat {
  <<< "geo.gen"
}
Hamiltonian = DFTB {
  SCC = Yes
  SCCTolerance = 1e-10
  MaxSCCIterations = 500
  ShellResolvedSCC = No
  Charge = 0.0
  SlaterKosterFiles = Type2FileNames {
    Prefix = "/tmp/pydftb_dyn__ynjxw8i/plain/"
    Separator = "-"
    Suffix = ".skf"
  }
  MaxAngularMomentum {
    O = "p"
    C = "p"
    H = "s"
  }
  Filling = Fermi {
    Temperature [K] = 0.0
  }
  Hybrid = LC {
    Screening = MatrixBased {}
  }

}
Analysis {
  PrintForces = Yes
  MullikenAnalysis = Yes
}
Options {
  WriteDetailedOut = Yes
  WriteResultsTag = Yes
  WriteAutotestTag = Yes
  TimingVerbosity = 0
}
ParserOptions {
  ParserVersion = 14
}
Parallel {
  UseOmpThreads = Yes
}
ExcitedState {
  Casida {
    NrOfExcitations = 4
    Symmetry = singlet
    StateOfInterest = 1
    Diagonaliser = Stratmann {}
    WriteTransitions = Yes
    WriteSPTransitions = Yes
    WriteTransitionDipole = Yes
    WriteMulliken = Yes
    ExcitedStateForces = Yes
  }
}
